// One order in, one row out. Everything the sheet will contain is decided here, so that the Google Sheets
// node has nothing to do but append — and so that a bad order is refused before it reaches the sheet, where
// a wrong row is far more annoying to fix than a 4xx is to read.
//
// The keys of the object returned below ARE the column headers: the Sheets node is set to
// "Map Automatically", which matches input fields to the header row by name. Rename a key here and you must
// rename the header in the sheet (and vice versa) — that pairing is the one thing to keep in step.
const req = $input.first().json;
const body = req.body ?? {};

const text = (value, max) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);

const orderId = text(body.orderId, 64);
const customer = text(body.customer, 120);
const phone = text(body.phone, 32);
const item = text(body.item, 200);
const note = text(body.note, 500);
const qty = Number(body.qty ?? 1);
const amountVnd = Number(body.amountVnd);

// Refusals, in the order a caller is most likely to get them wrong. Each names the field, because "400 bad
// request" with no field name is a support ticket.
if (!orderId) {
  throw new Error('orderId is required — it is what makes a row traceable back to the order');
}
if (!Number.isFinite(amountVnd) || amountVnd < 0) {
  throw new Error(`amountVnd must be a non-negative number, got ${JSON.stringify(body.amountVnd)}`);
}
if (!Number.isInteger(qty) || qty < 1) {
  throw new Error(`qty must be a whole number of 1 or more, got ${JSON.stringify(body.qty)}`);
}
if (!customer && !phone) {
  throw new Error('need customer or phone — a row identifying nobody cannot be followed up');
}

// ISO 8601 in UTC, not a local-time string: a spreadsheet of orders is read months later, often from another
// timezone, and "14/11/2026 23:05" with no offset is ambiguous. Format it for people in the sheet if you
// prefer, but keep one machine-readable column.
const receivedAt = new Date().toISOString();

return [
  {
    json: {
      receivedAt,
      orderId,
      customer,
      phone,
      item,
      qty,
      amountVnd,
      note,
      // Which execution wrote the row. Worth a column: when a row looks wrong, this is how you find the
      // execution that produced it in n8n's own list.
      executionId: $execution.id,
    },
  },
];

// What the caller is told. The row is already in the sheet by this point, so this is a receipt rather than a
// promise — and it carries the execution id so a support question can be traced without guesswork.
const row = $('Normalise the order').first().json;

return [
  {
    json: {
      logged: true,
      orderId: row.orderId,
      receivedAt: row.receivedAt,
      executionId: row.executionId,
    },
  },
];
